// JAH demo program — First-minute drill
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var __steps=["Enter and observe silently for 60 seconds", "Note emotional temperature, power, needs", "Write three predictions", "Check them by hour's end"];
__steps.forEach(function(s,i){console.log("step "+(i+1)+": "+s);});
check("step count", __steps.length, 4);
function drillOK(predictions, checked){ return (predictions>=3&&checked)?'read calibrated':'run the drill'; }
check("3 predictions checked", drillOK(3,true), "read calibrated");
check("no check", drillOK(3,false), "run the drill");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

